    assert_eq!(markdown_in(&root.join(".changeset/pre")), ["feature.md"]);
    assert_eq!(
        fs::read_to_string(root.join(".changeset/pre.json")).unwrap(),
        "{\n  \"mode\": \"pre\",\n  \"tag\": \"beta\"\n}\n",
