    assert_eq!(markdown_in(&root.join(".changeset/pre")), ["feature.md", "fix.md"]);

    let exit = callisto(root, &["pre", "exit"]);
    assert!(exit.status.success(), "{}", String::from_utf8_lossy(&exit.stderr));
    run_git(root, &["add", "-A"]);
    run_git(root, &["commit", "-q", "-m", "exit pre"]);
